import { afterAll, beforeAll, expect, it } from "vitest";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as attachmentService from "@/server/services/attachment-service";
import * as billingService from "@/server/services/billing-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

it("works", async () => {
  const a = await createTenant("aa", "free");
  const b = await createTenant("bb", "free");
  const ia = await issueRepo.insertIssue(issueInput(a.org.id, a.project.id), a.userIds.owner, 1 as never).catch(async (e) => { throw e; });
  const ib = await issueRepo.insertIssue(issueInput(b.org.id, b.project.id), b.userIds.owner, 1 as never);
  const MB = 1024 * 1024;
  const f1 = await attachmentService.addAttachment(a.actors.owner, { orgId: a.org.id, issueId: ia.id, filename: "a", contentType: "text/plain", sizeBytes: Math.round(0.4 * MB) });
  const f2 = await attachmentService.addAttachment(a.actors.owner, { orgId: a.org.id, issueId: ia.id, filename: "b", contentType: "text/plain", sizeBytes: Math.round(2.5 * MB) });
  await attachmentService.addAttachment(b.actors.owner, { orgId: b.org.id, issueId: ib.id, filename: "c", contentType: "text/plain", sizeBytes: Math.round(1.5 * MB) });
  expect((await billingService.checkLimit(a.org.id, "storageMb")).used).toBe(4);
  expect((await usageRepo.recomputeUsage(a.org.id)).storageMbUsed).toBe(4);
  await attachmentService.removeAttachment(a.actors.owner, { orgId: a.org.id, attachmentId: f1.id });
  expect((await usageRepo.getUsage(a.org.id)).storageMbUsed).toBe(3);
  await expect(attachmentService.removeAttachment(a.actors.owner, { orgId: a.org.id, attachmentId: f1.id })).rejects.toThrow(/not found/);
  expect((await usageRepo.getUsage(a.org.id)).storageMbUsed).toBe(3);
  await attachmentService.removeAttachment(a.actors.owner, { orgId: a.org.id, attachmentId: f2.id });
  expect((await usageRepo.recomputeUsage(a.org.id)).storageMbUsed).toBe(0);
});
EOF
